function thSpeakSafe(text, rate=0.94){if(typeof speakMiniGameTextSafe==='function')return speakMiniGameTextSafe(text,rate,'traffic-handle');}
const TH_SCENES = [{"id":"traffic_01_crosswalk","qs":[["Nếu đèn dành cho người đi bộ chưa cho phép qua đường nhưng phía trước đang vắng xe. Em nên xử lý thế nào?","Vẫn đứng chờ trên vỉa hè đến khi có tín hiệu cho phép qua đường.",["Vẫn đứng chờ trên vỉa hè đến khi có tín hiệu cho phép qua đường.","Chạy nhanh qua đường vì đang vắng xe.","Đi chéo sang phía bên kia để rút ngắn quãng đường.","Bước xuống lòng đường trước rồi mới quan sát."],"Nếu… thì…","Vạch sang đường và tín hiệu người đi bộ giúp người đi bộ qua đường ở vị trí dễ được phương tiện nhận biết hơn."],["Tình huống bất ngờ: Đèn dành cho người đi bộ chưa cho phép qua đường nhưng phía trước đang vắng xe. Việc nào nên làm trước?","Vẫn đứng chờ trên vỉa hè đến khi có tín hiệu cho phép qua đường.",["Vẫn đứng chờ trên vỉa hè đến khi có tín hiệu cho phép qua đường.","Chạy nhanh qua đường vì đang vắng xe.","Đi chéo sang phía bên kia để rút ngắn quãng đường.","Bước xuống lòng đường trước rồi mới quan sát."],"Phản xạ an toàn","Vạch sang đường và tín hiệu người đi bộ giúp người đi bộ qua đường ở vị trí dễ được phương tiện nhận biết hơn."],["Nếu tín hiệu đã cho phép đi nhưng có một chiếc xe vẫn đang tiến gần vạch sang đường. Em nên xử lý thế nào?","Dừng lại quan sát và chỉ tiếp tục khi chắc chắn xe đã nhường đường.",["Dừng lại quan sát và chỉ tiếp tục khi chắc chắn xe đã nhường đường.","Nhắm mắt đi thật nhanh qua vạch.","Buông tay người lớn để chạy trước.","Đứng giữa lòng đường chờ chiếc xe đi qua."],"Nếu… thì…","Dù có tín hiệu cho phép, người đi bộ vẫn cần quan sát để phòng phương tiện đi sai hoặc chưa dừng kịp."],["Tình huống bất ngờ: Tín hiệu đã cho phép đi nhưng có một chiếc xe vẫn đang tiến gần vạch sang đường. Việc nào nên làm trước?","Dừng lại quan sát và chỉ tiếp tục khi chắc chắn xe đã nhường đường.",["Dừng lại quan sát và chỉ tiếp tục khi chắc chắn xe đã nhường đường.","Nhắm mắt đi thật nhanh qua vạch.","Buông tay người lớn để chạy trước.","Đứng giữa lòng đường chờ chiếc xe đi qua."],"Phản xạ an toàn","Dù có tín hiệu cho phép, người đi bộ vẫn cần quan sát để phòng phương tiện đi sai hoặc chưa dừng kịp."]]},{"id":"traffic_02_red_light","qs":[["Nếu gia đình đang chờ ở ngã tư, một bạn thấy xe bên cạnh đã dừng nên muốn bước xuống đường. Em nên xử lý thế nào?","Nhắc bạn tiếp tục chờ tín hiệu dành cho người đi bộ rồi mới sang.",["Nhắc bạn tiếp tục chờ tín hiệu dành cho người đi bộ rồi mới sang.","Đi ngay vì các xe trước mặt đã dừng.","Đứng sát mép làn xe để nhìn rõ hơn.","Đi vòng ra phía sau cột đèn để sang đường."],"Nếu… thì…","Đèn đỏ đang điều khiển luồng giao thông; đi đúng tín hiệu giúp tránh xung đột giữa người và xe."],["Tình huống bất ngờ: Gia đình đang chờ ở ngã tư, một bạn thấy xe bên cạnh đã dừng nên muốn bước xuống đường. Việc nào nên làm trước?","Nhắc bạn tiếp tục chờ tín hiệu dành cho người đi bộ rồi mới sang.",["Nhắc bạn tiếp tục chờ tín hiệu dành cho người đi bộ rồi mới sang.","Đi ngay vì các xe trước mặt đã dừng.","Đứng sát mép làn xe để nhìn rõ hơn.","Đi vòng ra phía sau cột đèn để sang đường."],"Phản xạ an toàn","Đèn đỏ đang điều khiển luồng giao thông; đi đúng tín hiệu giúp tránh xung đột giữa người và xe."],["Nếu đèn xe ở một hướng đã đỏ nhưng biểu tượng người đi bộ vẫn chưa bật. Em nên xử lý thế nào?","Tiếp tục chờ biểu tượng người đi bộ cho phép qua đường.",["Tiếp tục chờ biểu tượng người đi bộ cho phép qua đường.","Qua ngay vì đã thấy một đèn đỏ.","Đi theo người khác dù chưa biết tín hiệu.","Bước xuống vạch rồi đứng chờ giữa đường."],"Nếu… thì…","Đèn dành cho xe và tín hiệu dành cho người đi bộ có thể hoạt động khác nhau."],["Tình huống bất ngờ: Đèn xe ở một hướng đã đỏ nhưng biểu tượng người đi bộ vẫn chưa bật. Việc nào nên làm trước?","Tiếp tục chờ biểu tượng người đi bộ cho phép qua đường.",["Tiếp tục chờ biểu tượng người đi bộ cho phép qua đường.","Qua ngay vì đã thấy một đèn đỏ.","Đi theo người khác dù chưa biết tín hiệu.","Bước xuống vạch rồi đứng chờ giữa đường."],"Phản xạ an toàn","Đèn dành cho xe và tín hiệu dành cho người đi bộ có thể hoạt động khác nhau."]]},{"id":"traffic_03_green_light","qs":[["Nếu các xe đang chạy theo đèn xanh, bạn nhỏ thấy đường bên kia rất gần. Em nên xử lý thế nào?","Đứng yên trên vỉa hè và chờ lượt qua đường của người đi bộ.",["Đứng yên trên vỉa hè và chờ lượt qua đường của người đi bộ.","Chạy cắt qua trước đầu xe.","Ra hiệu cho xe dừng để mình qua.","Đi men theo làn xe đến phía bên kia."],"Nếu… thì…","Đèn xanh cho xe nghĩa là các phương tiện đang có quyền di chuyển qua nút giao."],["Tình huống bất ngờ: Các xe đang chạy theo đèn xanh, bạn nhỏ thấy đường bên kia rất gần. Việc nào nên làm trước?","Đứng yên trên vỉa hè và chờ lượt qua đường của người đi bộ.",["Đứng yên trên vỉa hè và chờ lượt qua đường của người đi bộ.","Chạy cắt qua trước đầu xe.","Ra hiệu cho xe dừng để mình qua.","Đi men theo làn xe đến phía bên kia."],"Phản xạ an toàn","Đèn xanh cho xe nghĩa là các phương tiện đang có quyền di chuyển qua nút giao."],["Nếu biểu tượng người đi bộ vừa chuyển sang cho phép nhưng một xe đang trớn tiến tới. Em nên xử lý thế nào?","Chờ xe dừng hẳn rồi mới bước xuống vạch sang đường.",["Chờ xe dừng hẳn rồi mới bước xuống vạch sang đường.","Bước xuống ngay vì mình đang đúng luật.","Vẫy tay rồi chạy trước xe.","Đứng ngay trước đầu xe để xe phải dừng."],"Nếu… thì…","Quan sát cả tín hiệu và chuyển động thực tế của xe giúp giảm rủi ro do xe chưa kịp dừng."],["Tình huống bất ngờ: Biểu tượng người đi bộ vừa chuyển sang cho phép nhưng một xe đang trớn tiến tới. Việc nào nên làm trước?","Chờ xe dừng hẳn rồi mới bước xuống vạch sang đường.",["Chờ xe dừng hẳn rồi mới bước xuống vạch sang đường.","Bước xuống ngay vì mình đang đúng luật.","Vẫy tay rồi chạy trước xe.","Đứng ngay trước đầu xe để xe phải dừng."],"Phản xạ an toàn","Quan sát cả tín hiệu và chuyển động thực tế của xe giúp giảm rủi ro do xe chưa kịp dừng."]]},{"id":"traffic_04_motorbike_helmet","qs":[["Nếu bố đã nổ máy nhưng quai mũ của bé vẫn chưa cài. Em nên xử lý thế nào?","Đề nghị bố chờ để cài quai mũ đúng rồi mới khởi hành.",["Đề nghị bố chờ để cài quai mũ đúng rồi mới khởi hành.","Giữ mũ bằng một tay khi xe chạy.","Để quai mũ lỏng cho dễ chịu.","Không đội vì chỉ đi một đoạn ngắn."],"Nếu… thì…","Mũ chỉ bảo vệ tốt khi được giữ chắc trên đầu và không dễ văng ra khi có va chạm."],["Tình huống bất ngờ: Bố đã nổ máy nhưng quai mũ của bé vẫn chưa cài. Việc nào nên làm trước?","Đề nghị bố chờ để cài quai mũ đúng rồi mới khởi hành.",["Đề nghị bố chờ để cài quai mũ đúng rồi mới khởi hành.","Giữ mũ bằng một tay khi xe chạy.","Để quai mũ lỏng cho dễ chịu.","Không đội vì chỉ đi một đoạn ngắn."],"Phản xạ an toàn","Mũ chỉ bảo vệ tốt khi được giữ chắc trên đầu và không dễ văng ra khi có va chạm."],["Nếu bé đội chiếc mũ quá rộng, mũ cứ xoay sang một bên. Em nên xử lý thế nào?","Đổi sang mũ vừa đầu và cài quai đúng trước khi đi.",["Đổi sang mũ vừa đầu và cài quai đúng trước khi đi.","Chèn thêm khăn thật dày rồi đi luôn.","Dùng tay giữ mũ suốt đường.","Tháo mũ ra vì mũ gây vướng."],"Nếu… thì…","Mũ quá rộng hoặc đội lệch có thể không che và bảo vệ đúng vị trí cần thiết."],["Tình huống bất ngờ: Bé đội chiếc mũ quá rộng, mũ cứ xoay sang một bên. Việc nào nên làm trước?","Đổi sang mũ vừa đầu và cài quai đúng trước khi đi.",["Đổi sang mũ vừa đầu và cài quai đúng trước khi đi.","Chèn thêm khăn thật dày rồi đi luôn.","Dùng tay giữ mũ suốt đường.","Tháo mũ ra vì mũ gây vướng."],"Phản xạ an toàn","Mũ quá rộng hoặc đội lệch có thể không che và bảo vệ đúng vị trí cần thiết."]]},{"id":"traffic_05_wrong_helmet","qs":[["Nếu bé đã đội mũ nhưng quai mũ còn rất lỏng trước khi lên xe. Em nên xử lý thế nào?","Nhờ người lớn chỉnh và cài lại quai mũ cho chắc.",["Nhờ người lớn chỉnh và cài lại quai mũ cho chắc.","Kéo mũ xuống thấp che gần mắt.","Bỏ quai ra ngoài cho đỡ vướng.","Đi trước rồi chỉnh mũ sau."],"Nếu… thì…","Quai lỏng làm mũ dễ tuột khỏi đầu khi xe rung, phanh hoặc xảy ra va chạm."],["Tình huống bất ngờ: Bé đã đội mũ nhưng quai mũ còn rất lỏng trước khi lên xe. Việc nào nên làm trước?","Nhờ người lớn chỉnh và cài lại quai mũ cho chắc.",["Nhờ người lớn chỉnh và cài lại quai mũ cho chắc.","Kéo mũ xuống thấp che gần mắt.","Bỏ quai ra ngoài cho đỡ vướng.","Đi trước rồi chỉnh mũ sau."],"Phản xạ an toàn","Quai lỏng làm mũ dễ tuột khỏi đầu khi xe rung, phanh hoặc xảy ra va chạm."],["Nếu bé phát hiện khóa quai mũ không bấm được. Em nên xử lý thế nào?","Đổi sang chiếc mũ còn tốt trước khi đi xe.",["Đổi sang chiếc mũ còn tốt trước khi đi xe.","Buộc tạm quai bằng dây chun.","Đội mũ nhưng không cần cài.","Dùng mũ đồ chơi thay thế."],"Nếu… thì…","Mũ hư hỏng có thể giảm khả năng bảo vệ đầu khi cần."],["Tình huống bất ngờ: Bé phát hiện khóa quai mũ không bấm được. Việc nào nên làm trước?","Đổi sang chiếc mũ còn tốt trước khi đi xe.",["Đổi sang chiếc mũ còn tốt trước khi đi xe.","Buộc tạm quai bằng dây chun.","Đội mũ nhưng không cần cài.","Dùng mũ đồ chơi thay thế."],"Phản xạ an toàn","Mũ hư hỏng có thể giảm khả năng bảo vệ đầu khi cần."]]},{"id":"traffic_06_bicycle_safety","qs":[["Nếu bạn nhỏ đang đạp xe và muốn vừa đi vừa vẫy tay thật lâu với bố mẹ. Em nên xử lý thế nào?","Chỉ chào nhanh khi an toàn rồi tiếp tục giữ tay lái và nhìn đường.",["Chỉ chào nhanh khi an toàn rồi tiếp tục giữ tay lái và nhìn đường.","Buông cả hai tay để vẫy.","Quay hẳn người ra phía sau khi xe đang chạy.","Đạp nhanh hơn để chào xong sớm."],"Nếu… thì…","Giữ thăng bằng và kiểm soát hướng đi giúp xử lý tình huống bất ngờ tốt hơn."],["Tình huống bất ngờ: Bạn nhỏ đang đạp xe và muốn vừa đi vừa vẫy tay thật lâu với bố mẹ. Việc nào nên làm trước?","Chỉ chào nhanh khi an toàn rồi tiếp tục giữ tay lái và nhìn đường.",["Chỉ chào nhanh khi an toàn rồi tiếp tục giữ tay lái và nhìn đường.","Buông cả hai tay để vẫy.","Quay hẳn người ra phía sau khi xe đang chạy.","Đạp nhanh hơn để chào xong sớm."],"Phản xạ an toàn","Giữ thăng bằng và kiểm soát hướng đi giúp xử lý tình huống bất ngờ tốt hơn."],["Nếu một bạn đi xe đạp ngay sát phía sau người khác trên đường. Em nên xử lý thế nào?","Giảm tốc và tạo khoảng cách an toàn.",["Giảm tốc và tạo khoảng cách an toàn.","Đạp sát hơn để không ai chen vào.","Bấm chuông liên tục rồi giữ nguyên tốc độ.","Lách sang bên mà không quan sát."],"Nếu… thì…","Khoảng cách giúp có thời gian phanh hoặc đổi hướng khi phía trước dừng đột ngột."],["Tình huống bất ngờ: Một bạn đi xe đạp ngay sát phía sau người khác trên đường. Việc nào nên làm trước?","Giảm tốc và tạo khoảng cách an toàn.",["Giảm tốc và tạo khoảng cách an toàn.","Đạp sát hơn để không ai chen vào.","Bấm chuông liên tục rồi giữ nguyên tốc độ.","Lách sang bên mà không quan sát."],"Phản xạ an toàn","Khoảng cách giúp có thời gian phanh hoặc đổi hướng khi phía trước dừng đột ngột."]]},{"id":"traffic_07_bicycle_obstacle","qs":[["Nếu phía trước có vũng nước và một hòn đá nhỏ. Em nên xử lý thế nào?","Giảm tốc, quan sát xung quanh rồi đi vòng qua vật cản.",["Giảm tốc, quan sát xung quanh rồi đi vòng qua vật cản.","Đạp thật nhanh xuyên qua vũng nước.","Bẻ tay lái gấp sang bên kia.","Nhắm mắt và tiếp tục đi thẳng."],"Nếu… thì…","Đổi hướng đột ngột có thể làm mất thăng bằng hoặc va vào người khác."],["Tình huống bất ngờ: Phía trước có vũng nước và một hòn đá nhỏ. Việc nào nên làm trước?","Giảm tốc, quan sát xung quanh rồi đi vòng qua vật cản.",["Giảm tốc, quan sát xung quanh rồi đi vòng qua vật cản.","Đạp thật nhanh xuyên qua vũng nước.","Bẻ tay lái gấp sang bên kia.","Nhắm mắt và tiếp tục đi thẳng."],"Phản xạ an toàn","Đổi hướng đột ngột có thể làm mất thăng bằng hoặc va vào người khác."],["Nếu bé cần tránh một chướng ngại nhưng phía sau có người khác đang đạp xe. Em nên xử lý thế nào?","Giảm tốc, quan sát, báo hiệu rồi mới chuyển hướng khi đủ khoảng trống.",["Giảm tốc, quan sát, báo hiệu rồi mới chuyển hướng khi đủ khoảng trống.","Lập tức rẽ ngang để tránh.","Dừng giữa đường mà không báo hiệu.","Đua nhanh lên trước rồi rẽ."],"Nếu… thì…","Người đi phía sau cần biết mình sắp đổi hướng để có thời gian phản ứng."],["Tình huống bất ngờ: Bé cần tránh một chướng ngại nhưng phía sau có người khác đang đạp xe. Việc nào nên làm trước?","Giảm tốc, quan sát, báo hiệu rồi mới chuyển hướng khi đủ khoảng trống.",["Giảm tốc, quan sát, báo hiệu rồi mới chuyển hướng khi đủ khoảng trống.","Lập tức rẽ ngang để tránh.","Dừng giữa đường mà không báo hiệu.","Đua nhanh lên trước rồi rẽ."],"Phản xạ an toàn","Người đi phía sau cần biết mình sắp đổi hướng để có thời gian phản ứng."]]},{"id":"traffic_08_school_gate","qs":[["Nếu bé vừa xuống xe và muốn chạy băng qua giữa hai xe đang đỗ. Em nên xử lý thế nào?","Đi cùng người lớn theo lối an toàn, quan sát rồi mới qua.",["Đi cùng người lớn theo lối an toàn, quan sát rồi mới qua.","Chạy nhanh vì xe đang đỗ.","Luồn giữa các xe cho gần cổng.","Đứng sau xe đang lùi để chờ bạn."],"Nếu… thì…","Cổng trường đông người và phương tiện nên cần giảm xung đột, giữ tầm nhìn rõ."],["Tình huống bất ngờ: Bé vừa xuống xe và muốn chạy băng qua giữa hai xe đang đỗ. Việc nào nên làm trước?","Đi cùng người lớn theo lối an toàn, quan sát rồi mới qua.",["Đi cùng người lớn theo lối an toàn, quan sát rồi mới qua.","Chạy nhanh vì xe đang đỗ.","Luồn giữa các xe cho gần cổng.","Đứng sau xe đang lùi để chờ bạn."],"Phản xạ an toàn","Cổng trường đông người và phương tiện nên cần giảm xung đột, giữ tầm nhìn rõ."],["Nếu xe dừng cạnh vỉa hè nhưng bé định mở cửa phía lòng đường để xuống. Em nên xử lý thế nào?","Xuống ở phía sát vỉa hè theo hướng dẫn của người lớn.",["Xuống ở phía sát vỉa hè theo hướng dẫn của người lớn.","Mở cửa thật nhanh phía lòng đường.","Nhảy xuống khi xe chưa dừng hẳn.","Xuống bất kỳ phía nào vì xe đã bật đèn."],"Nếu… thì…","Xuống phía sát dòng xe đang chạy làm tăng nguy cơ va chạm."],["Tình huống bất ngờ: Xe dừng cạnh vỉa hè nhưng bé định mở cửa phía lòng đường để xuống. Việc nào nên làm trước?","Xuống ở phía sát vỉa hè theo hướng dẫn của người lớn.",["Xuống ở phía sát vỉa hè theo hướng dẫn của người lớn.","Mở cửa thật nhanh phía lòng đường.","Nhảy xuống khi xe chưa dừng hẳn.","Xuống bất kỳ phía nào vì xe đã bật đèn."],"Phản xạ an toàn","Xuống phía sát dòng xe đang chạy làm tăng nguy cơ va chạm."]]},{"id":"traffic_09_bus_stop","qs":[["Nếu xe buýt đang tới, bạn nhỏ muốn bước sát xuống mép đường để nhìn rõ hơn. Em nên xử lý thế nào?","Ở trong khu vực chờ và chỉ tiến lên khi xe đã dừng đúng chỗ.",["Ở trong khu vực chờ và chỉ tiến lên khi xe đã dừng đúng chỗ.","Chạy theo xe khi xe còn đang lăn bánh.","Đứng ngay trên phần đường xe buýt dừng.","Vẫy tay giữa lòng đường."],"Nếu… thì…","Xe buýt là phương tiện lớn và cần khoảng trống để áp sát điểm dừng an toàn."],["Tình huống bất ngờ: Xe buýt đang tới, bạn nhỏ muốn bước sát xuống mép đường để nhìn rõ hơn. Việc nào nên làm trước?","Ở trong khu vực chờ và chỉ tiến lên khi xe đã dừng đúng chỗ.",["Ở trong khu vực chờ và chỉ tiến lên khi xe đã dừng đúng chỗ.","Chạy theo xe khi xe còn đang lăn bánh.","Đứng ngay trên phần đường xe buýt dừng.","Vẫy tay giữa lòng đường."],"Phản xạ an toàn","Xe buýt là phương tiện lớn và cần khoảng trống để áp sát điểm dừng an toàn."],["Nếu nhiều người cùng chờ và cửa xe vừa mở. Em nên xử lý thế nào?","Giữ vị trí trong hàng, chờ người trước lên rồi mới tới lượt mình.",["Giữ vị trí trong hàng, chờ người trước lên rồi mới tới lượt mình.","Chen lên vì mình là trẻ em.","Chạy vòng sang cửa khác.","Đẩy người phía trước để lên nhanh."],"Nếu… thì…","Xếp hàng giúp mọi người lên xe trật tự, giảm chen lấn và té ngã."],["Tình huống bất ngờ: Nhiều người cùng chờ và cửa xe vừa mở. Việc nào nên làm trước?","Giữ vị trí trong hàng, chờ người trước lên rồi mới tới lượt mình.",["Giữ vị trí trong hàng, chờ người trước lên rồi mới tới lượt mình.","Chen lên vì mình là trẻ em.","Chạy vòng sang cửa khác.","Đẩy người phía trước để lên nhanh."],"Phản xạ an toàn","Xếp hàng giúp mọi người lên xe trật tự, giảm chen lấn và té ngã."]]},{"id":"traffic_10_getting_on_bus","qs":[["Nếu cửa xe đã mở nhưng xe vẫn đang nhích về phía trước. Em nên xử lý thế nào?","Đứng chờ đến khi xe dừng hẳn mới bước lên.",["Đứng chờ đến khi xe dừng hẳn mới bước lên.","Nhảy lên nhanh trước khi cửa đóng.","Bám vào tay vịn ngoài cửa khi xe chạy.","Chạy song song rồi bước lên."],"Nếu… thì…","Xe còn chuyển động có thể làm người lên xe mất thăng bằng hoặc rơi xuống."],["Tình huống bất ngờ: Cửa xe đã mở nhưng xe vẫn đang nhích về phía trước. Việc nào nên làm trước?","Đứng chờ đến khi xe dừng hẳn mới bước lên.",["Đứng chờ đến khi xe dừng hẳn mới bước lên.","Nhảy lên nhanh trước khi cửa đóng.","Bám vào tay vịn ngoài cửa khi xe chạy.","Chạy song song rồi bước lên."],"Phản xạ an toàn","Xe còn chuyển động có thể làm người lên xe mất thăng bằng hoặc rơi xuống."],["Nếu bạn nhỏ mang ba lô và đang bước lên xe sau mẹ. Em nên xử lý thế nào?","Đi từng bước, bám tay vịn và giữ khoảng cách với người trước.",["Đi từng bước, bám tay vịn và giữ khoảng cách với người trước.","Vừa bước vừa quay lại nói chuyện.","Chen sang bên người trước.","Nhảy hai bậc cùng lúc."],"Nếu… thì…","Bậc lên xuống có thể cao; tay vịn và trật tự giúp giảm nguy cơ vấp ngã."],["Tình huống bất ngờ: Bạn nhỏ mang ba lô và đang bước lên xe sau mẹ. Việc nào nên làm trước?","Đi từng bước, bám tay vịn và giữ khoảng cách với người trước.",["Đi từng bước, bám tay vịn và giữ khoảng cách với người trước.","Vừa bước vừa quay lại nói chuyện.","Chen sang bên người trước.","Nhảy hai bậc cùng lúc."],"Phản xạ an toàn","Bậc lên xuống có thể cao; tay vịn và trật tự giúp giảm nguy cơ vấp ngã."]]},{"id":"traffic_11_inside_bus","qs":[["Nếu một cụ già vừa lên xe nhưng các ghế thường đã kín. Em nên xử lý thế nào?","Chủ động nhường ghế và nói lời mời lịch sự.",["Chủ động nhường ghế và nói lời mời lịch sự.","Giả vờ ngủ để không phải nhường.","Đứng chắn lối đi để hỏi người khác.","Bảo cụ chờ người khác nhường."],"Nếu… thì…","Một số hành khách khó giữ thăng bằng hơn và cần chỗ ngồi an toàn hơn trẻ khỏe mạnh."],["Tình huống bất ngờ: Một cụ già vừa lên xe nhưng các ghế thường đã kín. Việc nào nên làm trước?","Chủ động nhường ghế và nói lời mời lịch sự.",["Chủ động nhường ghế và nói lời mời lịch sự.","Giả vờ ngủ để không phải nhường.","Đứng chắn lối đi để hỏi người khác.","Bảo cụ chờ người khác nhường."],"Phản xạ an toàn","Một số hành khách khó giữ thăng bằng hơn và cần chỗ ngồi an toàn hơn trẻ khỏe mạnh."],["Nếu bạn nhỏ muốn đi sang cuối xe khi xe đang chạy. Em nên xử lý thế nào?","Đi chậm, bám tay vịn và chỉ di chuyển khi thật cần thiết.",["Đi chậm, bám tay vịn và chỉ di chuyển khi thật cần thiết.","Chạy nhanh qua lối đi.","Đứng một chân để thử thăng bằng.","Bám vào người khác thay vì tay vịn."],"Nếu… thì…","Xe có thể tăng tốc, phanh hoặc rẽ bất ngờ khiến người đứng mất thăng bằng."],["Tình huống bất ngờ: Bạn nhỏ muốn đi sang cuối xe khi xe đang chạy. Việc nào nên làm trước?","Đi chậm, bám tay vịn và chỉ di chuyển khi thật cần thiết.",["Đi chậm, bám tay vịn và chỉ di chuyển khi thật cần thiết.","Chạy nhanh qua lối đi.","Đứng một chân để thử thăng bằng.","Bám vào người khác thay vì tay vịn."],"Phản xạ an toàn","Xe có thể tăng tốc, phanh hoặc rẽ bất ngờ khiến người đứng mất thăng bằng."]]},{"id":"traffic_12_getting_off_bus","qs":[["Nếu xe sắp tới điểm dừng nhưng vẫn đang lăn bánh. Em nên xử lý thế nào?","Đứng chuẩn bị, bám tay vịn và chờ xe dừng hẳn mới xuống.",["Đứng chuẩn bị, bám tay vịn và chờ xe dừng hẳn mới xuống.","Nhảy xuống khi xe chạy chậm.","Đứng sát mép cửa trước khi xe dừng.","Bước xuống lòng đường rồi chờ người thân."],"Nếu… thì…","Xuống khi xe còn chuyển động dễ mất thăng bằng và bị cuốn vào vùng xe chạy."],["Tình huống bất ngờ: Xe sắp tới điểm dừng nhưng vẫn đang lăn bánh. Việc nào nên làm trước?","Đứng chuẩn bị, bám tay vịn và chờ xe dừng hẳn mới xuống.",["Đứng chuẩn bị, bám tay vịn và chờ xe dừng hẳn mới xuống.","Nhảy xuống khi xe chạy chậm.","Đứng sát mép cửa trước khi xe dừng.","Bước xuống lòng đường rồi chờ người thân."],"Phản xạ an toàn","Xuống khi xe còn chuyển động dễ mất thăng bằng và bị cuốn vào vùng xe chạy."],["Nếu gia đình vừa xuống xe và cần sang bên kia đường. Em nên xử lý thế nào?","Đi đến nơi qua đường an toàn, quan sát rõ rồi mới sang.",["Đi đến nơi qua đường an toàn, quan sát rõ rồi mới sang.","Chạy vòng ngay trước đầu xe buýt.","Qua ngay sau đuôi xe vì tài xế không nhìn thấy.","Đứng giữa đường chờ xe buýt đi."],"Nếu… thì…","Xe buýt lớn che khuất người đi bộ và che cả các phương tiện đang tới."],["Tình huống bất ngờ: Gia đình vừa xuống xe và cần sang bên kia đường. Việc nào nên làm trước?","Đi đến nơi qua đường an toàn, quan sát rõ rồi mới sang.",["Đi đến nơi qua đường an toàn, quan sát rõ rồi mới sang.","Chạy vòng ngay trước đầu xe buýt.","Qua ngay sau đuôi xe vì tài xế không nhìn thấy.","Đứng giữa đường chờ xe buýt đi."],"Phản xạ an toàn","Xe buýt lớn che khuất người đi bộ và che cả các phương tiện đang tới."]]},{"id":"traffic_13_rainy_road","qs":[["Nếu trời mưa, phía trước có vũng nước và xe đang đi gần nhau. Em nên xử lý thế nào?","Đi chậm, giữ khoảng cách và tránh đánh lái gấp.",["Đi chậm, giữ khoảng cách và tránh đánh lái gấp.","Tăng tốc để thoát khỏi mưa.","Đi sát xe trước để tránh bị chen.","Phanh thật mạnh ngay trên vũng nước."],"Nếu… thì…","Mặt đường ướt làm độ bám giảm và quãng đường phanh có thể dài hơn."],["Tình huống bất ngờ: Trời mưa, phía trước có vũng nước và xe đang đi gần nhau. Việc nào nên làm trước?","Đi chậm, giữ khoảng cách và tránh đánh lái gấp.",["Đi chậm, giữ khoảng cách và tránh đánh lái gấp.","Tăng tốc để thoát khỏi mưa.","Đi sát xe trước để tránh bị chen.","Phanh thật mạnh ngay trên vũng nước."],"Phản xạ an toàn","Mặt đường ướt làm độ bám giảm và quãng đường phanh có thể dài hơn."],["Nếu mưa làm khung cảnh tối và khó nhìn xe phía trước. Em nên xử lý thế nào?","Bật đèn phù hợp và tiếp tục đi chậm, quan sát kỹ.",["Bật đèn phù hợp và tiếp tục đi chậm, quan sát kỹ.","Tắt đèn để đỡ chói.","Chỉ bấm còi thay cho việc quan sát.","Đi sát lề thật nhanh."],"Nếu… thì…","Mưa và trời tối làm tầm nhìn giảm, đèn giúp các bên nhận biết nhau sớm hơn."],["Tình huống bất ngờ: Mưa làm khung cảnh tối và khó nhìn xe phía trước. Việc nào nên làm trước?","Bật đèn phù hợp và tiếp tục đi chậm, quan sát kỹ.",["Bật đèn phù hợp và tiếp tục đi chậm, quan sát kỹ.","Tắt đèn để đỡ chói.","Chỉ bấm còi thay cho việc quan sát.","Đi sát lề thật nhanh."],"Phản xạ an toàn","Mưa và trời tối làm tầm nhìn giảm, đèn giúp các bên nhận biết nhau sớm hơn."]]},{"id":"traffic_14_night_road","qs":[["Nếu cả nhà đi bộ buổi tối trên con đường có đèn đường. Em nên xử lý thế nào?","Đi trên vỉa hè, sát người lớn và tránh bước xuống lòng đường.",["Đi trên vỉa hè, sát người lớn và tránh bước xuống lòng đường.","Đi dưới lòng đường vì ít người.","Mặc đồ tối và chạy qua đường nhanh.","Tắt đèn điện thoại để xe không bị chói."],"Nếu… thì…","Ánh sáng yếu khiến người lái xe khó nhận ra người đi bộ từ xa."],["Tình huống bất ngờ: Cả nhà đi bộ buổi tối trên con đường có đèn đường. Việc nào nên làm trước?","Đi trên vỉa hè, sát người lớn và tránh bước xuống lòng đường.",["Đi trên vỉa hè, sát người lớn và tránh bước xuống lòng đường.","Đi dưới lòng đường vì ít người.","Mặc đồ tối và chạy qua đường nhanh.","Tắt đèn điện thoại để xe không bị chói."],"Phản xạ an toàn","Ánh sáng yếu khiến người lái xe khó nhận ra người đi bộ từ xa."],["Nếu xe đi vào đoạn phố tối có người đi bộ gần đường. Em nên xử lý thế nào?","Giảm tốc và giữ khả năng dừng xe an toàn.",["Giảm tốc và giữ khả năng dừng xe an toàn.","Tăng tốc vì đường vắng.","Chỉ nhìn vào vùng sáng ngay trước xe.","Bấm còi liên tục rồi không cần giảm tốc."],"Nếu… thì…","Đèn giúp quan sát nhưng tầm nhìn ban đêm vẫn hạn chế hơn ban ngày."],["Tình huống bất ngờ: Xe đi vào đoạn phố tối có người đi bộ gần đường. Việc nào nên làm trước?","Giảm tốc và giữ khả năng dừng xe an toàn.",["Giảm tốc và giữ khả năng dừng xe an toàn.","Tăng tốc vì đường vắng.","Chỉ nhìn vào vùng sáng ngay trước xe.","Bấm còi liên tục rồi không cần giảm tốc."],"Phản xạ an toàn","Đèn giúp quan sát nhưng tầm nhìn ban đêm vẫn hạn chế hơn ban ngày."]]},{"id":"traffic_15_ambulance","qs":[["Nếu xe cứu thương bật tín hiệu đang tiến tới phía sau. Em nên xử lý thế nào?","Tìm cách nhường lối an toàn, giữ trật tự và không chặn đường.",["Tìm cách nhường lối an toàn, giữ trật tự và không chặn đường.","Tăng tốc chạy trước xe cứu thương.","Bám ngay sau xe cứu thương để đi nhanh.","Dừng đột ngột giữa làn xe."],"Nếu… thì…","Xe cứu thương cần di chuyển nhanh để đưa người bệnh hoặc nhân viên y tế tới nơi cần thiết."],["Tình huống bất ngờ: Xe cứu thương bật tín hiệu đang tiến tới phía sau. Việc nào nên làm trước?","Tìm cách nhường lối an toàn, giữ trật tự và không chặn đường.",["Tìm cách nhường lối an toàn, giữ trật tự và không chặn đường.","Tăng tốc chạy trước xe cứu thương.","Bám ngay sau xe cứu thương để đi nhanh.","Dừng đột ngột giữa làn xe."],"Phản xạ an toàn","Xe cứu thương cần di chuyển nhanh để đưa người bệnh hoặc nhân viên y tế tới nơi cần thiết."],["Nếu sau khi xe cứu thương đi qua, phía trước có khoảng trống lớn. Em nên xử lý thế nào?","Tiếp tục đi đúng làn với tốc độ phù hợp, không lao theo xe cứu thương.",["Tiếp tục đi đúng làn với tốc độ phù hợp, không lao theo xe cứu thương.","Tăng tốc bám sát vì đường đang trống.","Đi vào làn ngược chiều theo xe cứu thương.","Vượt các xe khác ngay lập tức."],"Nếu… thì…","Đi quá sát xe ưu tiên có thể gây nguy hiểm khi xe này phanh hoặc chuyển hướng đột ngột."],["Tình huống bất ngờ: Sau khi xe cứu thương đi qua, phía trước có khoảng trống lớn. Việc nào nên làm trước?","Tiếp tục đi đúng làn với tốc độ phù hợp, không lao theo xe cứu thương.",["Tiếp tục đi đúng làn với tốc độ phù hợp, không lao theo xe cứu thương.","Tăng tốc bám sát vì đường đang trống.","Đi vào làn ngược chiều theo xe cứu thương.","Vượt các xe khác ngay lập tức."],"Phản xạ an toàn","Đi quá sát xe ưu tiên có thể gây nguy hiểm khi xe này phanh hoặc chuyển hướng đột ngột."]]},{"id":"traffic_16_fire_truck","qs":[["Nếu xe cứu hỏa bật còi và đèn ưu tiên đang tới gần nút giao. Em nên xử lý thế nào?","Không chắn nút giao, nhường lối khi có thể và làm theo tín hiệu giao thông.",["Không chắn nút giao, nhường lối khi có thể và làm theo tín hiệu giao thông.","Cố vượt qua trước xe cứu hỏa.","Chạy sát bên xe để xem.","Dừng ngay giữa ngã tư."],"Nếu… thì…","Xe cứu hỏa cần đến hiện trường nhanh để xử lý cháy hoặc cứu nạn."],["Tình huống bất ngờ: Xe cứu hỏa bật còi và đèn ưu tiên đang tới gần nút giao. Việc nào nên làm trước?","Không chắn nút giao, nhường lối khi có thể và làm theo tín hiệu giao thông.",["Không chắn nút giao, nhường lối khi có thể và làm theo tín hiệu giao thông.","Cố vượt qua trước xe cứu hỏa.","Chạy sát bên xe để xem.","Dừng ngay giữa ngã tư."],"Phản xạ an toàn","Xe cứu hỏa cần đến hiện trường nhanh để xử lý cháy hoặc cứu nạn."],["Nếu bạn nhỏ tò mò muốn chạy theo xem xe cứu hỏa đi đâu. Em nên xử lý thế nào?","Ở lại nơi an toàn và không cản trở đường xe ưu tiên.",["Ở lại nơi an toàn và không cản trở đường xe ưu tiên.","Chạy theo trên vỉa hè thật gần.","Nhờ người lớn lái xe theo sau.","Đứng giữa đường chụp ảnh."],"Nếu… thì…","Khu vực xe cứu hỏa đến có thể có nguy hiểm và cần đường thông thoáng cho lực lượng làm nhiệm vụ."],["Tình huống bất ngờ: Bạn nhỏ tò mò muốn chạy theo xem xe cứu hỏa đi đâu. Việc nào nên làm trước?","Ở lại nơi an toàn và không cản trở đường xe ưu tiên.",["Ở lại nơi an toàn và không cản trở đường xe ưu tiên.","Chạy theo trên vỉa hè thật gần.","Nhờ người lớn lái xe theo sau.","Đứng giữa đường chụp ảnh."],"Phản xạ an toàn","Khu vực xe cứu hỏa đến có thể có nguy hiểm và cần đường thông thoáng cho lực lượng làm nhiệm vụ."]]},{"id":"traffic_17_railway_crossing","qs":[["Nếu rào chắn đã hạ nhưng tàu còn ở xa, bạn nhỏ muốn chui qua cho kịp. Em nên xử lý thế nào?","Tuyệt đối không đi qua; đứng chờ phía sau rào chắn.",["Tuyệt đối không đi qua; đứng chờ phía sau rào chắn.","Chạy thật nhanh trước khi tàu tới.","Đi vòng qua đầu rào chắn.","Đứng giữa đường ray để nhìn tàu."],"Nếu… thì…","Tàu hỏa rất nặng, chạy theo đường ray cố định và cần quãng đường rất dài để dừng."],["Tình huống bất ngờ: Rào chắn đã hạ nhưng tàu còn ở xa, bạn nhỏ muốn chui qua cho kịp. Việc nào nên làm trước?","Tuyệt đối không đi qua; đứng chờ phía sau rào chắn.",["Tuyệt đối không đi qua; đứng chờ phía sau rào chắn.","Chạy thật nhanh trước khi tàu tới.","Đi vòng qua đầu rào chắn.","Đứng giữa đường ray để nhìn tàu."],"Phản xạ an toàn","Tàu hỏa rất nặng, chạy theo đường ray cố định và cần quãng đường rất dài để dừng."],["Nếu một món đồ rơi gần đường ray khi tín hiệu cảnh báo đang bật. Em nên xử lý thế nào?","Không tự vào nhặt; báo người lớn hoặc nhân viên có trách nhiệm.",["Không tự vào nhặt; báo người lớn hoặc nhân viên có trách nhiệm.","Chạy vào nhặt thật nhanh.","Đợi tàu gần tới rồi nhặt.","Nhờ bạn nhỏ khác vào lấy."],"Nếu… thì…","Đường ray là khu vực nguy hiểm và tàu không thể tránh người hoặc vật cản bằng cách rẽ."],["Tình huống bất ngờ: Một món đồ rơi gần đường ray khi tín hiệu cảnh báo đang bật. Việc nào nên làm trước?","Không tự vào nhặt; báo người lớn hoặc nhân viên có trách nhiệm.",["Không tự vào nhặt; báo người lớn hoặc nhân viên có trách nhiệm.","Chạy vào nhặt thật nhanh.","Đợi tàu gần tới rồi nhặt.","Nhờ bạn nhỏ khác vào lấy."],"Phản xạ an toàn","Đường ray là khu vực nguy hiểm và tàu không thể tránh người hoặc vật cản bằng cách rẽ."]]},{"id":"traffic_18_train_station","qs":[["Nếu tàu sắp vào ga, bạn nhỏ muốn đứng sát mép để nhìn rõ. Em nên xử lý thế nào?","Lùi sau vạch an toàn và đứng cạnh người lớn.",["Lùi sau vạch an toàn và đứng cạnh người lớn.","Đứng ngay mép sân ga để chụp ảnh.","Đặt vali chắn lối đi.","Chạy dọc sân ga theo tàu."],"Nếu… thì…","Tàu vào ga có kích thước lớn, luồng gió và khoảng cách sát mép sân ga có thể nguy hiểm."],["Tình huống bất ngờ: Tàu sắp vào ga, bạn nhỏ muốn đứng sát mép để nhìn rõ. Việc nào nên làm trước?","Lùi sau vạch an toàn và đứng cạnh người lớn.",["Lùi sau vạch an toàn và đứng cạnh người lớn.","Đứng ngay mép sân ga để chụp ảnh.","Đặt vali chắn lối đi.","Chạy dọc sân ga theo tàu."],"Phản xạ an toàn","Tàu vào ga có kích thước lớn, luồng gió và khoảng cách sát mép sân ga có thể nguy hiểm."],["Nếu gia đình thấy một đoàn tàu đến nhưng chưa kiểm tra số/chuyến. Em nên xử lý thế nào?","Kiểm tra thông tin chuyến và cửa lên tàu trước khi bước lên.",["Kiểm tra thông tin chuyến và cửa lên tàu trước khi bước lên.","Lên tàu nào đến trước cũng được.","Chạy theo đoàn tàu để hỏi sau.","Đưa trẻ lên trước rồi người lớn kiểm tra sau."],"Nếu… thì…","Ga có nhiều chuyến; đi đúng thông tin và trật tự giúp tránh nhầm tàu và chen lấn."],["Tình huống bất ngờ: Gia đình thấy một đoàn tàu đến nhưng chưa kiểm tra số/chuyến. Việc nào nên làm trước?","Kiểm tra thông tin chuyến và cửa lên tàu trước khi bước lên.",["Kiểm tra thông tin chuyến và cửa lên tàu trước khi bước lên.","Lên tàu nào đến trước cũng được.","Chạy theo đoàn tàu để hỏi sau.","Đưa trẻ lên trước rồi người lớn kiểm tra sau."],"Phản xạ an toàn","Ga có nhiều chuyến; đi đúng thông tin và trật tự giúp tránh nhầm tàu và chen lấn."]]},{"id":"traffic_19_on_train","qs":[["Nếu bạn nhỏ muốn chạy sang cửa sổ bên kia khi tàu đang chạy. Em nên xử lý thế nào?","Đi chậm khi cần và bám chắc, tốt nhất ngồi đúng chỗ.",["Đi chậm khi cần và bám chắc, tốt nhất ngồi đúng chỗ.","Chạy thật nhanh trước khi tàu rung.","Leo lên ghế để nhìn rõ hơn.","Đứng giữa lối đi chơi."],"Nếu… thì…","Tàu có thể rung, tăng giảm tốc hoặc vào cua làm người mất thăng bằng."],["Tình huống bất ngờ: Bạn nhỏ muốn chạy sang cửa sổ bên kia khi tàu đang chạy. Việc nào nên làm trước?","Đi chậm khi cần và bám chắc, tốt nhất ngồi đúng chỗ.",["Đi chậm khi cần và bám chắc, tốt nhất ngồi đúng chỗ.","Chạy thật nhanh trước khi tàu rung.","Leo lên ghế để nhìn rõ hơn.","Đứng giữa lối đi chơi."],"Phản xạ an toàn","Tàu có thể rung, tăng giảm tốc hoặc vào cua làm người mất thăng bằng."],["Nếu vali lớn đang nằm giữa lối đi trong toa. Em nên xử lý thế nào?","Đặt vali vào giá hoặc vị trí hành lý phù hợp.",["Đặt vali vào giá hoặc vị trí hành lý phù hợp.","Để nguyên để dễ lấy.","Xếp vali trước cửa ra vào.","Cho trẻ ngồi lên vali giữa lối."],"Nếu… thì…","Lối đi thông thoáng giúp mọi người di chuyển và thoát ra khi cần."],["Tình huống bất ngờ: Vali lớn đang nằm giữa lối đi trong toa. Việc nào nên làm trước?","Đặt vali vào giá hoặc vị trí hành lý phù hợp.",["Đặt vali vào giá hoặc vị trí hành lý phù hợp.","Để nguyên để dễ lấy.","Xếp vali trước cửa ra vào.","Cho trẻ ngồi lên vali giữa lối."],"Phản xạ an toàn","Lối đi thông thoáng giúp mọi người di chuyển và thoát ra khi cần."]]},{"id":"traffic_20_airport","qs":[["Nếu bạn nhỏ thấy một cửa hàng thú vị ở xa và muốn tự chạy tới. Em nên xử lý thế nào?","Báo người lớn và chỉ đi cùng gia đình.",["Báo người lớn và chỉ đi cùng gia đình.","Tự chạy đi rồi quay lại sau.","Để vali tại chỗ để đi nhanh.","Đi theo một gia đình khác vì cùng hướng."],"Nếu… thì…","Sân bay rộng, nhiều khu chức năng và đông người nên dễ đi nhầm hoặc thất lạc."],["Tình huống bất ngờ: Bạn nhỏ thấy một cửa hàng thú vị ở xa và muốn tự chạy tới. Việc nào nên làm trước?","Báo người lớn và chỉ đi cùng gia đình.",["Báo người lớn và chỉ đi cùng gia đình.","Tự chạy đi rồi quay lại sau.","Để vali tại chỗ để đi nhanh.","Đi theo một gia đình khác vì cùng hướng."],"Phản xạ an toàn","Sân bay rộng, nhiều khu chức năng và đông người nên dễ đi nhầm hoặc thất lạc."],["Nếu gia đình thấy hai biển chỉ dẫn tới các khu khác nhau. Em nên xử lý thế nào?","Đối chiếu thông tin chuyến bay và theo đúng biển chỉ dẫn.",["Đối chiếu thông tin chuyến bay và theo đúng biển chỉ dẫn.","Đi theo đám đông đông nhất.","Chọn cổng gần nhất.","Đợi đến sát giờ mới tìm cổng."],"Nếu… thì…","Mỗi chuyến bay có thông tin riêng; nhầm cổng có thể làm lỡ chuyến."],["Tình huống bất ngờ: Gia đình thấy hai biển chỉ dẫn tới các khu khác nhau. Việc nào nên làm trước?","Đối chiếu thông tin chuyến bay và theo đúng biển chỉ dẫn.",["Đối chiếu thông tin chuyến bay và theo đúng biển chỉ dẫn.","Đi theo đám đông đông nhất.","Chọn cổng gần nhất.","Đợi đến sát giờ mới tìm cổng."],"Phản xạ an toàn","Mỗi chuyến bay có thông tin riêng; nhầm cổng có thể làm lỡ chuyến."]]},{"id":"traffic_21_airplane_boarding","qs":[["Nếu cửa lên máy bay đã mở, nhiều người đang chờ. Em nên xử lý thế nào?","Giữ vị trí trong hàng và chuẩn bị giấy tờ khi tới lượt.",["Giữ vị trí trong hàng và chuẩn bị giấy tờ khi tới lượt.","Chen lên trước để chọn ghế.","Chạy một mình qua ống lồng.","Đưa vé cho bạn giữ rồi đi trước."],"Nếu… thì…","Lên máy bay theo thứ tự giúp kiểm soát hành khách và tránh chen lấn ở lối hẹp."],["Tình huống bất ngờ: Cửa lên máy bay đã mở, nhiều người đang chờ. Việc nào nên làm trước?","Giữ vị trí trong hàng và chuẩn bị giấy tờ khi tới lượt.",["Giữ vị trí trong hàng và chuẩn bị giấy tờ khi tới lượt.","Chen lên trước để chọn ghế.","Chạy một mình qua ống lồng.","Đưa vé cho bạn giữ rồi đi trước."],"Phản xạ an toàn","Lên máy bay theo thứ tự giúp kiểm soát hành khách và tránh chen lấn ở lối hẹp."],["Nếu một túi lớn được đặt giữa lối đi trong máy bay. Em nên xử lý thế nào?","Nhờ người lớn hoặc tiếp viên cất vào vị trí phù hợp.",["Nhờ người lớn hoặc tiếp viên cất vào vị trí phù hợp.","Để dưới lối đi cho dễ lấy.","Ngồi lên túi để giữ.","Đặt túi trước cửa thoát."],"Nếu… thì…","Hành lý để sai vị trí có thể rơi, chắn lối hoặc gây khó khăn khi di chuyển."],["Tình huống bất ngờ: Một túi lớn được đặt giữa lối đi trong máy bay. Việc nào nên làm trước?","Nhờ người lớn hoặc tiếp viên cất vào vị trí phù hợp.",["Nhờ người lớn hoặc tiếp viên cất vào vị trí phù hợp.","Để dưới lối đi cho dễ lấy.","Ngồi lên túi để giữ.","Đặt túi trước cửa thoát."],"Phản xạ an toàn","Hành lý để sai vị trí có thể rơi, chắn lối hoặc gây khó khăn khi di chuyển."]]},{"id":"traffic_22_ferry_boat","qs":[["Nếu tàu đang chạy, một bạn muốn tháo áo phao vì thấy nóng. Em nên xử lý thế nào?","Giữ áo phao đúng cách và làm theo hướng dẫn an toàn.",["Giữ áo phao đúng cách và làm theo hướng dẫn an toàn.","Tháo ra rồi cầm trên tay.","Treo áo phao lên lan can.","Đổi áo với người khác để chơi."],"Nếu… thì…","Áo phao giúp tăng khả năng nổi nếu chẳng may rơi xuống nước."],["Tình huống bất ngờ: Tàu đang chạy, một bạn muốn tháo áo phao vì thấy nóng. Việc nào nên làm trước?","Giữ áo phao đúng cách và làm theo hướng dẫn an toàn.",["Giữ áo phao đúng cách và làm theo hướng dẫn an toàn.","Tháo ra rồi cầm trên tay.","Treo áo phao lên lan can.","Đổi áo với người khác để chơi."],"Phản xạ an toàn","Áo phao giúp tăng khả năng nổi nếu chẳng may rơi xuống nước."],["Nếu bé muốn trèo lên lan can để nhìn mặt nước rõ hơn. Em nên xử lý thế nào?","Đứng sau lan can, cạnh người lớn và quan sát từ vị trí an toàn.",["Đứng sau lan can, cạnh người lớn và quan sát từ vị trí an toàn.","Ngồi lên lan can nhưng giữ bằng một tay.","Nhờ bố bế cao qua lan can.","Đứng trên ghế sát mép tàu."],"Nếu… thì…","Tàu rung hoặc sóng có thể làm mất thăng bằng và rơi xuống nước."],["Tình huống bất ngờ: Bé muốn trèo lên lan can để nhìn mặt nước rõ hơn. Việc nào nên làm trước?","Đứng sau lan can, cạnh người lớn và quan sát từ vị trí an toàn.",["Đứng sau lan can, cạnh người lớn và quan sát từ vị trí an toàn.","Ngồi lên lan can nhưng giữ bằng một tay.","Nhờ bố bế cao qua lan can.","Đứng trên ghế sát mép tàu."],"Phản xạ an toàn","Tàu rung hoặc sóng có thể làm mất thăng bằng và rơi xuống nước."]]},{"id":"traffic_23_taxi_pickup","qs":[["Nếu taxi dừng sát vỉa hè, bé định mở cửa phía có xe đang chạy. Em nên xử lý thế nào?","Mở cửa và xuống phía sát vỉa hè khi điều kiện cho phép.",["Mở cửa và xuống phía sát vỉa hè khi điều kiện cho phép.","Mở cửa thật nhanh phía lòng đường.","Bước xuống trước khi xe dừng.","Chạy vòng trước đầu taxi."],"Nếu… thì…","Lên xuống phía lòng đường làm người dễ va chạm với phương tiện đi ngang."],["Tình huống bất ngờ: Taxi dừng sát vỉa hè, bé định mở cửa phía có xe đang chạy. Việc nào nên làm trước?","Mở cửa và xuống phía sát vỉa hè khi điều kiện cho phép.",["Mở cửa và xuống phía sát vỉa hè khi điều kiện cho phép.","Mở cửa thật nhanh phía lòng đường.","Bước xuống trước khi xe dừng.","Chạy vòng trước đầu taxi."],"Phản xạ an toàn","Lên xuống phía lòng đường làm người dễ va chạm với phương tiện đi ngang."],["Nếu taxi bắt đầu chạy nhưng bé chưa cài dây an toàn. Em nên xử lý thế nào?","Cài dây an toàn ngay và ngồi đúng tư thế.",["Cài dây an toàn ngay và ngồi đúng tư thế.","Ngồi sát cửa sổ và không cần dây.","Đứng lên nhìn đường.","Ngồi vào lòng người lớn thay dây an toàn."],"Nếu… thì…","Taxi vẫn là ô tô và có thể phanh gấp hoặc xảy ra va chạm."],["Tình huống bất ngờ: Taxi bắt đầu chạy nhưng bé chưa cài dây an toàn. Việc nào nên làm trước?","Cài dây an toàn ngay và ngồi đúng tư thế.",["Cài dây an toàn ngay và ngồi đúng tư thế.","Ngồi sát cửa sổ và không cần dây.","Đứng lên nhìn đường.","Ngồi vào lòng người lớn thay dây an toàn."],"Phản xạ an toàn","Taxi vẫn là ô tô và có thể phanh gấp hoặc xảy ra va chạm."]]},{"id":"traffic_24_parking_lot","qs":[["Nếu bé muốn chạy tắt giữa hai hàng ô tô để tới cửa nhanh hơn. Em nên xử lý thế nào?","Đi cùng người lớn theo lối đánh dấu và quan sát kỹ.",["Đi cùng người lớn theo lối đánh dấu và quan sát kỹ.","Chạy nhanh vì xe trong bãi đi chậm.","Đi sát đuôi xe đang nổ máy.","Trốn giữa hai xe để chờ bố mẹ."],"Nếu… thì…","Bãi đỗ có nhiều xe chuyển động chậm nhưng tầm nhìn của tài xế bị hạn chế bởi các xe khác."],["Tình huống bất ngờ: Bé muốn chạy tắt giữa hai hàng ô tô để tới cửa nhanh hơn. Việc nào nên làm trước?","Đi cùng người lớn theo lối đánh dấu và quan sát kỹ.",["Đi cùng người lớn theo lối đánh dấu và quan sát kỹ.","Chạy nhanh vì xe trong bãi đi chậm.","Đi sát đuôi xe đang nổ máy.","Trốn giữa hai xe để chờ bố mẹ."],"Phản xạ an toàn","Bãi đỗ có nhiều xe chuyển động chậm nhưng tầm nhìn của tài xế bị hạn chế bởi các xe khác."],["Nếu một chiếc xe bật đèn lùi khi gia đình đang đi gần đó. Em nên xử lý thế nào?","Dừng ở vị trí an toàn, tránh xa phía sau xe và chờ xe đi xong.",["Dừng ở vị trí an toàn, tránh xa phía sau xe và chờ xe đi xong.","Đi nhanh qua ngay sau xe.","Gõ vào cốp xe để tài xế biết.","Đứng yên sát cản sau."],"Nếu… thì…","Tài xế có thể có điểm mù và không nhìn thấy trẻ nhỏ ngay sau xe."],["Tình huống bất ngờ: Một chiếc xe bật đèn lùi khi gia đình đang đi gần đó. Việc nào nên làm trước?","Dừng ở vị trí an toàn, tránh xa phía sau xe và chờ xe đi xong.",["Dừng ở vị trí an toàn, tránh xa phía sau xe và chờ xe đi xong.","Đi nhanh qua ngay sau xe.","Gõ vào cốp xe để tài xế biết.","Đứng yên sát cản sau."],"Phản xạ an toàn","Tài xế có thể có điểm mù và không nhìn thấy trẻ nhỏ ngay sau xe."]]},{"id":"traffic_25_car_seatbelt","qs":[["Nếu xe chuẩn bị chạy nhưng một bạn chưa bấm khóa dây. Em nên xử lý thế nào?","Chờ bạn cài dây đúng rồi mới khởi hành.",["Chờ bạn cài dây đúng rồi mới khởi hành.","Đi chậm nên không cần dây.","Cầm dây bằng tay thay vì cài.","Chỉ người ngồi ghế trước cần dây."],"Nếu… thì…","Dây an toàn giữ cơ thể đúng vị trí khi xe phanh gấp hoặc va chạm."],["Tình huống bất ngờ: Xe chuẩn bị chạy nhưng một bạn chưa bấm khóa dây. Việc nào nên làm trước?","Chờ bạn cài dây đúng rồi mới khởi hành.",["Chờ bạn cài dây đúng rồi mới khởi hành.","Đi chậm nên không cần dây.","Cầm dây bằng tay thay vì cài.","Chỉ người ngồi ghế trước cần dây."],"Phản xạ an toàn","Dây an toàn giữ cơ thể đúng vị trí khi xe phanh gấp hoặc va chạm."],["Nếu bé luồn dây ra sau lưng vì thấy vướng vai. Em nên xử lý thế nào?","Đeo dây đúng vị trí và điều chỉnh cho vừa.",["Đeo dây đúng vị trí và điều chỉnh cho vừa.","Giữ nguyên vì vẫn có khóa cài.","Nới dây thật lỏng.","Ngồi nghiêng để dây không chạm người."],"Nếu… thì…","Dây đặt sai có thể giảm khả năng giữ cơ thể và gây chấn thương khi có lực lớn."],["Tình huống bất ngờ: Bé luồn dây ra sau lưng vì thấy vướng vai. Việc nào nên làm trước?","Đeo dây đúng vị trí và điều chỉnh cho vừa.",["Đeo dây đúng vị trí và điều chỉnh cho vừa.","Giữ nguyên vì vẫn có khóa cài.","Nới dây thật lỏng.","Ngồi nghiêng để dây không chạm người."],"Phản xạ an toàn","Dây đặt sai có thể giảm khả năng giữ cơ thể và gây chấn thương khi có lực lớn."]]},{"id":"traffic_26_child_car_seat","qs":[["Nếu gia đình chuẩn bị đi ô tô nhưng em bé chưa được cài dây ghế riêng. Em nên xử lý thế nào?","Cài dây ghế an toàn chắc chắn trước khi xe chạy.",["Cài dây ghế an toàn chắc chắn trước khi xe chạy.","Bế em trên tay suốt chuyến đi.","Để em ngồi ghế người lớn không dây.","Cho em đứng giữa hai ghế."],"Nếu… thì…","Cơ thể trẻ nhỏ cần hệ thống giữ phù hợp với kích thước để được bảo vệ tốt hơn."],["Tình huống bất ngờ: Gia đình chuẩn bị đi ô tô nhưng em bé chưa được cài dây ghế riêng. Việc nào nên làm trước?","Cài dây ghế an toàn chắc chắn trước khi xe chạy.",["Cài dây ghế an toàn chắc chắn trước khi xe chạy.","Bế em trên tay suốt chuyến đi.","Để em ngồi ghế người lớn không dây.","Cho em đứng giữa hai ghế."],"Phản xạ an toàn","Cơ thể trẻ nhỏ cần hệ thống giữ phù hợp với kích thước để được bảo vệ tốt hơn."],["Nếu ghế an toàn lắc mạnh khi mẹ thử kéo nhẹ. Em nên xử lý thế nào?","Dừng lại kiểm tra và lắp chắc theo hướng dẫn trước khi đi.",["Dừng lại kiểm tra và lắp chắc theo hướng dẫn trước khi đi.","Kê thêm gối rồi dùng tiếp.","Giữ ghế bằng tay khi xe chạy.","Bỏ dây dưới chân em cho thoải mái."],"Nếu… thì…","Ghế hoặc dây lỏng có thể di chuyển nhiều khi phanh, làm giảm khả năng bảo vệ."],["Tình huống bất ngờ: Ghế an toàn lắc mạnh khi mẹ thử kéo nhẹ. Việc nào nên làm trước?","Dừng lại kiểm tra và lắp chắc theo hướng dẫn trước khi đi.",["Dừng lại kiểm tra và lắp chắc theo hướng dẫn trước khi đi.","Kê thêm gối rồi dùng tiếp.","Giữ ghế bằng tay khi xe chạy.","Bỏ dây dưới chân em cho thoải mái."],"Phản xạ an toàn","Ghế hoặc dây lỏng có thể di chuyển nhiều khi phanh, làm giảm khả năng bảo vệ."]]},{"id":"traffic_27_traffic_jam","qs":[["Nếu đường đang kẹt nhưng làn ngược chiều có vẻ trống. Em nên xử lý thế nào?","Tiếp tục đi đúng làn và chờ dòng xe di chuyển.",["Tiếp tục đi đúng làn và chờ dòng xe di chuyển.","Lấn sang làn ngược chiều để vượt.","Đi lên vỉa hè để tránh kẹt.","Bám sát xe trước không để khoảng trống."],"Nếu… thì…","Chen lấn làm dòng xe rối hơn, tăng nguy cơ va chạm và có thể khiến ùn tắc nặng hơn."],["Tình huống bất ngờ: Đường đang kẹt nhưng làn ngược chiều có vẻ trống. Việc nào nên làm trước?","Tiếp tục đi đúng làn và chờ dòng xe di chuyển.",["Tiếp tục đi đúng làn và chờ dòng xe di chuyển.","Lấn sang làn ngược chiều để vượt.","Đi lên vỉa hè để tránh kẹt.","Bám sát xe trước không để khoảng trống."],"Phản xạ an toàn","Chen lấn làm dòng xe rối hơn, tăng nguy cơ va chạm và có thể khiến ùn tắc nặng hơn."],["Nếu các xe chỉ nhích từng chút một. Em nên xử lý thế nào?","Kiên nhẫn, giữ khoảng cách và quan sát dòng xe.",["Kiên nhẫn, giữ khoảng cách và quan sát dòng xe.","Bấm còi liên tục để xe trước đi nhanh.","Chuyển làn liên tục tìm chỗ trống.","Đi thật sát cản xe trước."],"Nếu… thì…","Khoảng cách giúp xử lý khi xe trước dừng; còi liên tục không làm hết tắc và gây căng thẳng, ồn ào."],["Tình huống bất ngờ: Các xe chỉ nhích từng chút một. Việc nào nên làm trước?","Kiên nhẫn, giữ khoảng cách và quan sát dòng xe.",["Kiên nhẫn, giữ khoảng cách và quan sát dòng xe.","Bấm còi liên tục để xe trước đi nhanh.","Chuyển làn liên tục tìm chỗ trống.","Đi thật sát cản xe trước."],"Phản xạ an toàn","Khoảng cách giúp xử lý khi xe trước dừng; còi liên tục không làm hết tắc và gây căng thẳng, ồn ào."]]},{"id":"traffic_28_road_work","qs":[["Nếu biển báo yêu cầu đi vòng nhưng đường thẳng phía trước có vẻ ngắn hơn. Em nên xử lý thế nào?","Đi theo hướng vòng được chỉ dẫn.",["Đi theo hướng vòng được chỉ dẫn.","Lách qua rào chắn vì đường ngắn.","Đi sát máy công trình để vượt nhanh.","Bỏ qua cọc tiêu nếu không thấy công nhân."],"Nếu… thì…","Công trường có máy móc, mặt đường thay đổi và người làm việc nên cần tuân theo luồng tạm thời."],["Tình huống bất ngờ: Biển báo yêu cầu đi vòng nhưng đường thẳng phía trước có vẻ ngắn hơn. Việc nào nên làm trước?","Đi theo hướng vòng được chỉ dẫn.",["Đi theo hướng vòng được chỉ dẫn.","Lách qua rào chắn vì đường ngắn.","Đi sát máy công trình để vượt nhanh.","Bỏ qua cọc tiêu nếu không thấy công nhân."],"Phản xạ an toàn","Công trường có máy móc, mặt đường thay đổi và người làm việc nên cần tuân theo luồng tạm thời."],["Nếu một cọc tiêu chắn đúng lối bé muốn đi xe đạp. Em nên xử lý thế nào?","Đi theo lối được mở sẵn, không đẩy cọc tiêu sang chỗ khác.",["Đi theo lối được mở sẵn, không đẩy cọc tiêu sang chỗ khác.","Dời cọc sang lề rồi đi qua.","Luồn dưới rào chắn.","Đi vào phần đường máy xúc đang làm việc."],"Nếu… thì…","Các vật này đánh dấu vùng nguy hiểm và hướng dẫn người đi đường tránh khu vực thi công."],["Tình huống bất ngờ: Một cọc tiêu chắn đúng lối bé muốn đi xe đạp. Việc nào nên làm trước?","Đi theo lối được mở sẵn, không đẩy cọc tiêu sang chỗ khác.",["Đi theo lối được mở sẵn, không đẩy cọc tiêu sang chỗ khác.","Dời cọc sang lề rồi đi qua.","Luồn dưới rào chắn.","Đi vào phần đường máy xúc đang làm việc."],"Phản xạ an toàn","Các vật này đánh dấu vùng nguy hiểm và hướng dẫn người đi đường tránh khu vực thi công."]]},{"id":"traffic_29_accident_prevention","qs":[["Nếu quả bóng lăn xuống vạch sang đường khi tín hiệu đang báo dừng. Em nên xử lý thế nào?","Đứng lại, báo người lớn và chờ lúc an toàn mới lấy bóng.",["Đứng lại, báo người lớn và chờ lúc an toàn mới lấy bóng.","Chạy thật nhanh lấy bóng rồi quay lại.","Nhờ bạn chạy ra lấy.","Bước xuống đường nhưng chỉ nhìn vào quả bóng."],"Nếu… thì…","Khi mải nhìn theo bóng, trẻ dễ quên quan sát xe đang tới và người lái có thể không kịp dừng."],["Tình huống bất ngờ: Quả bóng lăn xuống vạch sang đường khi tín hiệu đang báo dừng. Việc nào nên làm trước?","Đứng lại, báo người lớn và chờ lúc an toàn mới lấy bóng.",["Đứng lại, báo người lớn và chờ lúc an toàn mới lấy bóng.","Chạy thật nhanh lấy bóng rồi quay lại.","Nhờ bạn chạy ra lấy.","Bước xuống đường nhưng chỉ nhìn vào quả bóng."],"Phản xạ an toàn","Khi mải nhìn theo bóng, trẻ dễ quên quan sát xe đang tới và người lái có thể không kịp dừng."],["Nếu bé rất tiếc quả bóng mới và muốn lao ra lấy ngay. Em nên xử lý thế nào?","Chờ người lớn hỗ trợ và chỉ lấy khi giao thông đã an toàn.",["Chờ người lớn hỗ trợ và chỉ lấy khi giao thông đã an toàn.","Bất chấp tín hiệu để lấy vì bóng mới.","Đứng giữa đường ra hiệu cho xe dừng.","Chạy vòng sau xe đang tới."],"Nếu… thì…","Đồ vật có thể thay thế hoặc lấy lại sau, còn chạy vào dòng xe tạo nguy cơ chấn thương nghiêm trọng."],["Tình huống bất ngờ: Bé rất tiếc quả bóng mới và muốn lao ra lấy ngay. Việc nào nên làm trước?","Chờ người lớn hỗ trợ và chỉ lấy khi giao thông đã an toàn.",["Chờ người lớn hỗ trợ và chỉ lấy khi giao thông đã an toàn.","Bất chấp tín hiệu để lấy vì bóng mới.","Đứng giữa đường ra hiệu cho xe dừng.","Chạy vòng sau xe đang tới."],"Phản xạ an toàn","Đồ vật có thể thay thế hoặc lấy lại sau, còn chạy vào dòng xe tạo nguy cơ chấn thương nghiêm trọng."]]},{"id":"traffic_30_transport_hub","qs":[["Nếu gia đình cần đi từ vỉa hè sang điểm xe buýt qua nhiều làn phương tiện. Em nên xử lý thế nào?","Theo lối sang đường và hàng rào dẫn hướng, quan sát từng làn trước khi đi.",["Theo lối sang đường và hàng rào dẫn hướng, quan sát từng làn trước khi đi.","Đi tắt qua làn taxi.","Chạy xuyên qua làn xe đạp.","Leo qua hàng rào để rút ngắn đường."],"Nếu… thì…","Khu trung chuyển có xe buýt, taxi, xe đạp và người đi bộ nên phân luồng giúp giảm xung đột."],["Tình huống bất ngờ: Gia đình cần đi từ vỉa hè sang điểm xe buýt qua nhiều làn phương tiện. Việc nào nên làm trước?","Theo lối sang đường và hàng rào dẫn hướng, quan sát từng làn trước khi đi.",["Theo lối sang đường và hàng rào dẫn hướng, quan sát từng làn trước khi đi.","Đi tắt qua làn taxi.","Chạy xuyên qua làn xe đạp.","Leo qua hàng rào để rút ngắn đường."],"Phản xạ an toàn","Khu trung chuyển có xe buýt, taxi, xe đạp và người đi bộ nên phân luồng giúp giảm xung đột."],["Nếu gia đình cần đi taxi nhưng đang đứng ở khu xe buýt. Em nên xử lý thế nào?","Di chuyển theo biển chỉ dẫn tới điểm đón taxi.",["Di chuyển theo biển chỉ dẫn tới điểm đón taxi.","Đứng giữa đường gọi taxi.","Chặn một xe buýt để hỏi taxi.","Ra làn xe đạp chờ taxi."],"Nếu… thì…","Mỗi loại phương tiện có khu đón trả riêng để tránh lộn xộn và giúp hành khách lên xe an toàn."],["Tình huống bất ngờ: Gia đình cần đi taxi nhưng đang đứng ở khu xe buýt. Việc nào nên làm trước?","Di chuyển theo biển chỉ dẫn tới điểm đón taxi.",["Di chuyển theo biển chỉ dẫn tới điểm đón taxi.","Đứng giữa đường gọi taxi.","Chặn một xe buýt để hỏi taxi.","Ra làn xe đạp chờ taxi."],"Phản xạ an toàn","Mỗi loại phương tiện có khu đón trả riêng để tránh lộn xộn và giúp hành khách lên xe an toàn."]]}].map(s=>({...s,image:(typeof resolveClass2VietnameseImageSrc==='function' ? (resolveClass2VietnameseImageSrc(s.id) || `assets/images/${s.id}.jpg`) : `assets/images/${s.id}.jpg`)}));
let th_deck=[],th_round=0,th_cycle=0,th_score=0,th_streak=0,th_best=0,th_locked=false,th_current=null;
const th_qState={};
function th_shuffle(arr){const a=arr.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function th_buildDeck(){th_deck=th_shuffle(TH_SCENES);th_cycle++;if(th_current&&th_deck.length>1&&th_deck[0].id===th_current.scene.id){[th_deck[0],th_deck[1]]=[th_deck[1],th_deck[0]];}}
function th_pickQ(scene){let st=th_qState[scene.id];if(!st)st=th_qState[scene.id]={deck:[],last:-1};if(!st.deck.length){st.deck=th_shuffle(scene.qs.map((_,i)=>i));if(st.deck.length>1&&st.deck[0]===st.last)[st.deck[0],st.deck[1]]=[st.deck[1],st.deck[0]];}const idx=st.deck.shift();st.last=idx;return scene.qs[idx];}
function th_next(){if(typeof isMiniGameActive==='function'&&!isMiniGameActive('traffic-handle'))return;if(!th_deck.length)th_buildDeck();const scene=th_deck.shift();th_current={scene,q:th_pickQ(scene)};th_round++;th_locked=false;th_render();}
function th_esc(s){return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function th_ensureStyles(){if(document.getElementById('th-style'))return;const s=document.createElement('style');s.id='th-style';s.textContent=`
@keyframes thShake{0%,100%{transform:translateX(0)}25%{transform:translateX(-7px)}50%{transform:translateX(7px)}75%{transform:translateX(-4px)}}
@keyframes thGlow{0%,100%{box-shadow:none}50%{box-shadow:0 0 30px rgba(249,115,22,.28)}}
.th-shake{animation:thShake .3s ease}.th-correct{animation:thGlow .65s ease}
.th-layout{display:grid;grid-template-columns:minmax(300px,410px) minmax(0,1fr);gap:14px;align-items:stretch}.th-picwrap{position:relative;aspect-ratio:1/1;width:100%;overflow:hidden;border-radius:22px}.th-pic{width:100%;height:100%;object-fit:cover;display:block}.th-opts{display:grid;grid-template-columns:1fr;gap:9px;align-content:center}.th-opt{min-height:58px;text-align:left}
@media(max-width:900px){.th-layout{grid-template-columns:minmax(260px,350px) minmax(0,1fr);gap:10px}.th-opt{min-height:54px}}@media(max-width:700px){.th-layout{grid-template-columns:1fr}.th-picwrap{max-width:430px;margin:0 auto}.th-opts{grid-template-columns:1fr}.th-opt{min-height:50px}}`;
document.head.appendChild(s);}
function startTrafficHandleGame(){th_ensureStyles();th_deck=[];th_round=0;th_cycle=0;th_score=0;th_streak=0;th_best=0;th_locked=false;th_current=null;Object.keys(th_qState).forEach(k=>delete th_qState[k]);th_next();}
function th_render(){const box=document.getElementById('game-play-container');if(!box||!th_current)return;const [question,correct,rawOptions,type,explain]=th_current.q;const options=th_shuffle(rawOptions);box.innerHTML=`
<div class="rounded-[28px] border-2 border-orange-200 bg-gradient-to-b from-orange-50/80 via-rose-50/45 to-amber-50/55 p-2.5 md:p-3"><div class="flex items-center justify-between gap-2 mb-2"><div class="flex items-center gap-2 min-w-0"><span class="px-3 py-1.5 rounded-full bg-white/90 border-orange-200 text-orange-700 font-black text-xs md:text-sm shrink-0">⚡ Lượt ${th_round}</span><span class="px-2.5 py-1 rounded-full bg-orange-100 text-orange-700 font-black text-[10px] md:text-xs">${th_esc(type)}</span></div><div class="flex gap-1.5 shrink-0"><span class="px-2.5 py-1.5 rounded-full bg-amber-50 border border-amber-200 text-amber-700 font-black text-xs md:text-sm">⭐ ${th_score}</span><span class="px-2.5 py-1.5 rounded-full bg-rose-50 border border-rose-200 text-rose-600 font-black text-xs md:text-sm">🔥 x${th_streak}</span><span class="px-2.5 py-1.5 rounded-full bg-purple-50 border border-purple-200 text-purple-600 font-black text-xs md:text-sm">🏆 ${th_best}</span></div></div>
<div data-minigame-question class="mb-2 px-3 py-2 rounded-2xl bg-white/90 border-orange-200 text-center font-black text-slate-700 text-sm md:text-lg leading-snug">${th_esc(question)}</div>
<div class="th-layout"><div class="th-picwrap"><img class="th-pic" src="${th_current.scene.image}" alt="Tranh tình huống giao thông"></div><div class="th-opts">${options.map((op,i)=>`<button class="th-opt px-4 py-2.5 rounded-2xl border-2 ${['bg-white border-sky-200 hover:bg-sky-50','bg-white border-emerald-200 hover:bg-emerald-50','bg-white border-amber-200 hover:bg-amber-50','bg-white border-violet-200 hover:bg-violet-50'][i]} text-slate-700 font-extrabold text-sm md:text-[15px] leading-snug shadow-sm transition-all" data-answer="${th_esc(op)}" onclick="th_choose(this)">${th_esc(op)}</button>`).join('')}<div id="th-feedback" class="min-h-[32px] flex items-center justify-center text-center text-xs md:text-sm font-black text-orange-700">🧠 Bé đọc kỹ, suy nghĩ thật thoải mái rồi chọn cách xử lý an toàn nhất nhé!</div></div></div></div>`;
if(typeof setMiniGameQuestionAudio==='function')setMiniGameQuestionAudio(question,0.92);if(typeof thSpeakSafe==='function')setTimeout(()=>thSpeakSafe(question,0.92),140);}
function th_choose(btn){if(th_locked||!th_current)return;const answer=btn.dataset.answer;const correct=th_current.q[1];const explain=th_current.q[4]||'';if(answer===correct){th_locked=true;th_score+=12+Math.min(th_streak,5)*2;th_streak++;th_best=Math.max(th_best,th_streak);btn.classList.add('bg-emerald-100','border-emerald-400','text-emerald-800','th-correct');const fb=document.getElementById('th-feedback');if(fb)fb.innerHTML=`⚡ Phản xạ an toàn! <span class="ml-1">${th_esc(explain)}</span>`;if(typeof playAudio==='function')playAudio('correct');if(typeof confetti==='function')confetti({particleCount:55,spread:70,origin:{y:.72}});if(typeof thSpeakSafe==='function')thSpeakSafe('Chính xác! Bé xử lý tình huống rất tốt.',1.0);setTimeout(th_next,1500);}else{th_streak=0;btn.classList.add('th-shake','border-rose-400','bg-rose-50');setTimeout(()=>btn.classList.remove('th-shake','border-rose-400','bg-rose-50'),360);const fb=document.getElementById('th-feedback');if(fb)fb.textContent='🚨 Cách này có thể làm tình huống nguy hiểm hơn. Hãy chọn phương án bình tĩnh và an toàn nhất!';if(typeof playAudio==='function')playAudio('wrong');}}
window.startTrafficHandleGame=startTrafficHandleGame;window.th_choose=th_choose;
